import * as THREE from 'three';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { CONFIG } from './config.js';

// Low-frequency light is still generated by 3D particles; fine entities stay full resolution.
export function createHazePass(renderer, scene, camera) {
  const target = new THREE.WebGLRenderTarget(1, 1, { type: THREE.HalfFloatType, depthBuffer: false });
  const pass = new ShaderPass({
    uniforms: { tDiffuse: { value: null }, hazeTexture: { value: null } },
    vertexShader: 'varying vec2 uvScreen; void main(){ uvScreen=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); }',
    fragmentShader: 'uniform sampler2D tDiffuse,hazeTexture; varying vec2 uvScreen; void main(){ gl_FragColor=vec4(texture2D(tDiffuse,uvScreen).rgb+texture2D(hazeTexture,uvScreen).rgb,1.); }',
  });
  pass.uniforms.hazeTexture.value = target.texture;
  const clearColor = new THREE.Color();
  return {
    pass,
    resize(width, height, dpr) { target.setSize(Math.max(1, Math.round(width * dpr * CONFIG.hazeRenderScale)), Math.max(1, Math.round(height * dpr * CONFIG.hazeRenderScale))); },
    render() {
      const previousTarget = renderer.getRenderTarget(), mask = camera.layers.mask, alpha = renderer.getClearAlpha();
      renderer.getClearColor(clearColor);
      try {
        renderer.setRenderTarget(target); renderer.setClearColor(0, 0); renderer.clear();
        camera.layers.set(1); renderer.render(scene, camera);
      } finally {
        camera.layers.mask = mask; renderer.setRenderTarget(previousTarget); renderer.setClearColor(clearColor, alpha);
      }
    },
  };
}
